LONG = {}
def L(id, who, why=None, matters=None, extra=None):
    intro = [("Who " + who[0], who[1])] + ([why] if why else [])
    LONG[id] = dict(intro=intro, outro=[matters] if matters else [])

L("adam-eve", ("Adam & Eve were", """Adam and Eve were the first human beings, created by God and placed in the Garden of Eden. Genesis describes God forming Adam from the dust and breathing life into him, then making Eve from Adam’s side as his partner — equal in worth and made for each other. They were given the job of caring for the earth and ruling it on God’s behalf. Genesis says both were made “in the image of God,” which is why every human life has dignity."""),
  matters=("Why they matter today", """Their story explains why the world is both beautiful and broken. It also contains the first promise of rescue: a descendant of Eve would crush the serpent. The New Testament calls Jesus the “last Adam,” who undid what Adam lost."""))
L("cain-abel", ("Cain & Abel were", """Cain and Abel were the first two sons of Adam and Eve, born outside Eden. Cain, the firstborn, became a farmer; Abel kept flocks. Their story is the first account of worship in the Bible — and the first murder."""),
  matters=("Why it matters today", """God warned Cain that sin was crouching at his door and that he could master it. Cain’s story shows how jealousy left unchecked grows into something terrible — and that even then, God showed Cain mercy. Hebrews remembers Abel as a man of faith."""))
L("noah", ("Noah was", """Noah lived in the tenth generation from Adam, in a world the Bible describes as filled with violence and corruption. His father Lamech named him Noah, which sounds like the Hebrew word for “comfort” or “rest.” Genesis says he was righteous, blameless among the people of his time, and that he “walked faithfully with God.” He had three sons — Shem, Ham and Japheth — and the Bible traces every nation on earth back to them."""),
  why=("Why God chose Noah", """Genesis says simply that “Noah found favor in the eyes of the Lord.” Hebrews says he built the ark “by faith,” taking God’s warning seriously about things not yet seen. Noah obeyed God completely for decades, building a huge boat on dry land while the world around him carried on as usual."""),
  matters=("Why Noah matters today", """Noah’s story shows both God’s justice against evil and His mercy in providing a way of rescue. The rainbow still reminds us of God’s promise. Peter later compared the ark to how God saves His people through Jesus."""))
L("abraham", ("Abraham was", """Abraham, first called Abram, was born around 2000 BC in Ur of the Chaldeans, a wealthy city in Mesopotamia (modern-day Iraq). His family worshiped other gods. He married Sarai, and they had no children. His father Terah moved the family to Haran in northern Mesopotamia, and it was there, at 75, that God called Abram to leave everything."""),
  why=("Why God chose Abraham", """The Bible doesn’t say exactly why God chose Abraham, but it emphasizes his response: he believed God and obeyed, leaving home without knowing where he was going. God’s plan was bigger than one man — through Abraham’s family, “all peoples on earth will be blessed.” That promise was fulfilled through Jesus, a descendant of Abraham."""),
  matters=("Why Abraham matters today", """Abraham is called the father of faith. Paul says that anyone who trusts God the way Abraham did is his spiritual child. His life shows faith that waits, stumbles, grows, and finally trusts God even with what it loves most."""))
L("sarah", ("Sarah was", """Sarah, first called Sarai, was Abraham’s wife and half-sister. She was famously beautiful. For most of her life she couldn’t have children — a deep source of pain and shame in her culture. She left her home and family to follow God’s call with Abraham at age 65."""),
  matters=("Why Sarah matters today", """Sarah laughed at God’s promise, and God turned her laugh of doubt into a laugh of joy. She is called the mother of nations, and Hebrews honors her faith: “she considered Him faithful who had made the promise.”"""))
L("jacob", ("Jacob was", """Jacob was the son of Isaac and Rebekah and the grandson of Abraham. He was a twin, born just after his brother Esau, clutching his heel. He grew up quiet and clever, his mother’s favorite, and he spent much of his early life scheming to get what he wanted."""),
  why=("Why God chose Jacob", """God told Rebekah before the twins were born that the older would serve the younger. The Bible doesn’t say it was because Jacob was better — he wasn’t. God chose to work through a flawed, scheming man, and spent decades changing him, until the trickster “Jacob” became “Israel.”"""),
  matters=("Why Jacob matters today", """The whole nation of Israel is named after him, and his twelve sons became its twelve tribes. Jacob’s life shows that God keeps His promises even through deeply imperfect people, and that wrestling honestly with God can leave you limping — and blessed."""))
L("joseph-egypt", ("Joseph was", """Joseph was the eleventh of Jacob’s twelve sons and the first son of Rachel, the wife Jacob loved most. Born when Jacob was old, he was his father’s favorite, which made his older brothers jealous. He was a dreamer, and God gave him the ability to understand dreams."""),
  matters=("Why Joseph matters today", """Joseph suffered betrayal, slavery, false accusation and prison, yet stayed faithful and refused revenge. His story is one of the clearest pictures in the Bible of God working through suffering: “You intended to harm me, but God intended it for good.” He saved Egypt and his own family from famine."""))
L("moses", ("Moses was", """Moses was born in Egypt around the 15th or 13th century BC to Israelite slaves from the tribe of Levi, Amram and Jochebed. His older siblings were Miriam and Aaron. His name is related to an Egyptian word for “son” and a Hebrew word for “drawn out,” because Pharaoh’s daughter drew him out of the water. He grew up as a member of Egypt’s royal household, then spent 40 years as a shepherd in the desert of Midian, and finally 40 years leading Israel."""),
  why=("Why God chose Moses", """The Bible doesn’t say God chose Moses because of his talents. In fact, Moses argued that he wasn’t the right person and begged God to send someone else. But Numbers calls him “more humble than anyone else on the face of the earth.” God used his unique background — raised in Pharaoh’s palace, trained in the desert — and promised, “I will be with you.”"""),
  matters=("Why Moses matters today", """Moses is the great lawgiver and prophet of the Old Testament. Through him God freed Israel from slavery, gave the Ten Commandments, and formed a nation. The Exodus is the defining rescue story of the Old Testament, and Jesus celebrated it at the Last Supper, giving it new meaning."""))
L("aaron", ("Aaron was", """Aaron was the older brother of Moses and Miriam, from the tribe of Levi. While Moses grew up in the palace and fled to Midian, Aaron remained among the enslaved Israelites in Egypt. He was a good speaker, so God chose him to be Moses’ spokesman."""),
  matters=("Why Aaron matters today", """Aaron became Israel’s first high priest, and all later priests descended from him. His failures (the golden calf) and his calling both point forward to Jesus, whom Hebrews calls the perfect High Priest."""))
L("miriam", ("Miriam was", """Miriam was the older sister of Aaron and Moses. She is the first woman in the Bible called a prophet. The prophet Micah later names her alongside Moses and Aaron as one of the three leaders God sent to bring Israel out of Egypt."""),
  matters=("Why Miriam matters today", """Miriam’s quick thinking saved her baby brother, and her song after the Red Sea is one of the oldest poems in the Bible. Her story also shows God’s discipline and mercy when she grew jealous."""))
L("joshua", ("Joshua was", """Joshua, son of Nun, was from the tribe of Ephraim. Born a slave in Egypt, he became Moses’ assistant and military commander during the wilderness years. His original name was Hoshea, “salvation”; Moses changed it to Yehoshua, “the Lord saves” — the same name as Jesus (Yeshua)."""),
  matters=("Why Joshua matters today", """Joshua led Israel into the land God had promised Abraham. His courage came from God’s repeated promise, “I will be with you,” and his famous choice still challenges people: “As for me and my house, we will serve the Lord.”"""))
L("caleb", ("Caleb was", """Caleb, son of Jephunneh, was a leader from the tribe of Judah and one of the twelve spies Moses sent into Canaan. He was 40 at the time."""),
  matters=("Why Caleb matters today", """Caleb trusted God when the majority didn’t, waited 45 years for God’s promise, and at 85 still asked for the hardest mountain. He shows that faith doesn’t retire."""))
L("rahab", ("Rahab was", """Rahab was a Canaanite woman living in Jericho, working as a prostitute, in a house built into the city wall. She was an outsider in every way — not an Israelite, and with a shameful profession — yet she believed that Israel’s God was the true God."""),
  matters=("Why Rahab matters today", """Rahab is named in Jesus’ family tree and praised for her faith in Hebrews and James. Her story shows that God welcomes anyone who turns to Him, no matter where they come from."""))
L("deborah", ("Deborah was", """Deborah lived in the hill country of Ephraim during the time of the judges, about 1200 BC, when Israel had no king and kept falling into cycles of disobedience and oppression. She was a prophet and Israel’s judge — its leader and settler of disputes — the only woman to hold that role. She was married to a man named Lappidoth."""),
  matters=("Why Deborah matters today", """Deborah was a woman of wisdom and courage at a time when Israel’s men hesitated. She shows that God raises up the leaders He chooses."""))
L("gideon", ("Gideon was", """Gideon was the youngest son in a family from the clan of Abiezer, the weakest clan in the tribe of Manasseh. For seven years the Midianites had raided Israel at harvest time, stealing crops and livestock, and the people hid in caves. Gideon was threshing wheat secretly in a winepress when God called him."""),
  why=("Why God chose Gideon", """Gideon himself asked that question. God called him “mighty warrior” while he was hiding — naming what God would make of him. God then deliberately shrank his army so that no one could say Israel won by its own strength."""),
  matters=("Why Gideon matters today", """Gideon shows that God is patient with our fears and that victory comes from God, not numbers. His later mistakes also warn that early faith must be guarded."""))
L("samson", ("Samson was", """Samson was born to a couple from the tribe of Dan who had been unable to have children. An angel announced his birth and said he would be a Nazirite — set apart to God — from birth. He judged Israel for 20 years during the period when the Philistines dominated them."""),
  matters=("Why Samson matters today", """Samson was given enormous strength but struggled with self-control and wasted much of his calling. Yet in his final prayer, he turned back to God. Hebrews lists him among the heroes of faith — a reminder of God’s grace toward deeply flawed people."""))
L("ruth", ("Ruth was", """Ruth was a Moabite woman. Moab was a neighboring nation often hostile to Israel, and Moabites worshiped a god named Chemosh. She married an Israelite named Mahlon whose family had moved to Moab during a famine. After her husband died, she chose to follow her mother-in-law Naomi to Bethlehem and to worship the God of Israel."""),
  matters=("Why Ruth matters today", """Ruth’s loyalty and kindness turned a story of tragedy into hope. A foreigner became the great-grandmother of King David and an ancestor of Jesus. Her story shows God’s care for outsiders, widows and the poor."""))
L("hannah", ("Hannah was", """Hannah was one of two wives of Elkanah, from the hill country of Ephraim. His other wife, Peninnah, had children and mocked Hannah for having none. Every year the family traveled to Shiloh, where the tabernacle stood, to worship."""),
  matters=("Why Hannah matters today", """Hannah poured out her pain honestly to God, kept her promise when He answered, and her son Samuel became one of Israel’s greatest leaders. Her song of praise echoes in Mary’s song centuries later."""))
L("samuel", ("Samuel was", """Samuel was the son of Hannah and Elkanah, given to God’s service as a young child and raised at the tabernacle in Shiloh by the high priest Eli. He became Israel’s last judge, a prophet, and the one who anointed Israel’s first two kings."""),
  matters=("Why Samuel matters today", """Samuel’s first prayer — “Speak, Lord, for Your servant is listening” — is still a model of how to approach God. He led Israel faithfully through its move from judges to kings."""))
L("saul", ("Saul was", """Saul, son of Kish, was from the small tribe of Benjamin. He was tall, handsome and humble at first. He became Israel’s first king around 1050 BC, chosen when the people demanded a king like the other nations."""),
  matters=("Why Saul matters today", """Saul started with every advantage but kept choosing his own way over God’s, then let jealousy consume him. His life is a warning: “To obey is better than sacrifice.”"""))
L("david", ("David was", """David was the youngest of eight sons of Jesse, a farmer in Bethlehem, from the tribe of Judah. He was the great-grandson of Ruth and Boaz. He grew up as a shepherd, defending his flock from lions and bears, and was a gifted musician and poet. He became Israel’s second and greatest king, reigning about 40 years around 1000 BC."""),
  why=("Why God chose David", """When Samuel came to anoint a king, God passed over all of David’s older, more impressive brothers and said, “The Lord does not look at the things people look at. People look at the outward appearance, but the Lord looks at the heart.” Later God called David “a man after My own heart.”"""),
  matters=("Why David matters today", """David was a giant-killer, a poet, a warrior and a king — and also an adulterer and murderer who repented deeply. God promised that his throne would last forever, a promise fulfilled in Jesus, called the “Son of David.” His psalms still give words to people’s prayers."""))
L("solomon", ("Solomon was", """Solomon was the son of King David and Bathsheba. He became Israel’s third king around 970 BC and reigned 40 years, a time of peace and great wealth. God gave him extraordinary wisdom."""),
  matters=("Why Solomon matters today", """Solomon built the Temple and wrote much of Israel’s wisdom literature, including Proverbs. But his heart drifted from God in his later years — a warning that wisdom isn’t enough without faithfulness."""))
L("esther", ("Esther was", """Esther lived in Susa, the Persian capital, around 480 BC, in the reign of King Xerxes (Ahasuerus). She was a Jewish orphan descended from exiles taken from Jerusalem, raised by her older cousin Mordecai. Her Hebrew name was Hadassah, meaning “myrtle.”"""),
  matters=("Why Esther matters today", """The book of Esther never mentions God’s name, yet God is clearly at work behind the scenes. Esther risked her life to save her people, and Jews still celebrate it every year at Purim."""))
L("hezekiah", ("Hezekiah was", """Hezekiah became king of Judah around 715 BC at age 25, following his idolatrous father Ahaz. He reigned 29 years in Jerusalem, during the time of the prophet Isaiah and the rising Assyrian empire."""),
  matters=("Why Hezekiah matters today", """Hezekiah turned his nation back to God and, when facing an impossible threat, took it straight to God in prayer. God answered."""))
L("josiah", ("Josiah was", """Josiah became king of Judah around 640 BC at just eight years old. His grandfather Manasseh and father Amon had filled the land with idol worship."""),
  matters=("Why Josiah matters today", """Josiah’s reforms began when he heard God’s Word read and took it seriously. One person who responds to Scripture can change a nation."""))
L("elijah", ("Elijah was", """Elijah was a prophet from Tishbe in Gilead, east of the Jordan River, active around 860 BC in the northern kingdom of Israel. He wore a garment of hair with a leather belt. His name means “My God is the Lord” — exactly the message of his life, in a time when King Ahab and Queen Jezebel promoted the worship of Baal."""),
  matters=("Why Elijah matters today", """Elijah is one of the greatest prophets in the Bible. He confronted kings, saw fire fall from heaven — and also felt burned out and alone, until God met him in a gentle whisper. James says he was “a human being, even as we are,” and his prayers were powerful."""))
L("elisha", ("Elisha was", """Elisha, son of Shaphat, was a farmer from Abel Meholah plowing with twelve pairs of oxen when Elijah called him. He served as Elijah’s apprentice, then as a prophet in Israel for about 50 years."""),
  matters=("Why Elisha matters today", """Elisha’s ministry was full of compassion — for widows, families, foreigners and even enemies. He showed that God’s power is often seen in caring for ordinary people’s needs."""))
L("isaiah", ("Isaiah was", """Isaiah, son of Amoz, was a prophet in Jerusalem from about 740 to 700 BC, during the reigns of Uzziah, Jotham, Ahaz and Hezekiah. He was married and had two sons whose names carried prophetic messages. He seems to have had access to the royal court."""),
  matters=("Why Isaiah matters today", """The book of Isaiah is the Old Testament book most quoted in the New Testament. It describes the coming Messiah in remarkable detail, and Jesus read from Isaiah to announce His own mission."""))
L("jeremiah", ("Jeremiah was", """Jeremiah was the son of a priest named Hilkiah from Anathoth, a village near Jerusalem. He was called as a young man around 627 BC and prophesied for about 40 years, through the last kings of Judah and the destruction of Jerusalem by Babylon in 586 BC."""),
  matters=("Why Jeremiah matters today", """Jeremiah delivered a hard message faithfully and suffered for it. Yet he also gave some of the most hopeful promises in the Bible, including the “new covenant” Jesus spoke of at the Last Supper."""))
L("daniel", ("Daniel was", """Daniel was a young man from a noble family in Judah, taken to Babylon in 605 BC when King Nebuchadnezzar first conquered Jerusalem. The Babylonians gave him a new name, Belteshazzar, and trained him for government service. He served in the courts of Babylon and Persia for about 70 years."""),
  matters=("Why Daniel matters today", """Daniel stayed faithful to God for a lifetime in a culture that wasn’t his own, serving his rulers well without compromising his worship. His visions also point to God’s eternal kingdom and the “Son of Man.”"""))
L("shadrach", ("they were", """Hananiah, Mishael and Azariah were Daniel’s friends, young men from Judah taken to Babylon and given the names Shadrach, Meshach and Abednego. They were trained with Daniel and promoted to govern the province of Babylon."""),
  matters=("Why they matter today", """Their words — “even if He does not” — are one of the Bible’s greatest statements of faith: trusting God whether or not He rescues you."""))
L("jonah", ("Jonah was", """Jonah, son of Amittai, was a prophet from Gath Hepher in Galilee around 780 BC. He had earlier prophesied that King Jeroboam II would restore Israel’s borders. Nineveh, where God sent him, was the capital of Assyria, the most feared and brutal empire of the time."""),
  matters=("Why Jonah matters today", """Jonah’s story is about God’s mercy reaching even Israel’s enemies — and about a prophet who didn’t want them to have it. Jesus pointed to Jonah’s three days in the fish as a sign of His own resurrection."""))
L("job", ("Job was", """Job lived in the land of Uz, probably east of Israel, likely in the time of the patriarchs. He was the greatest man among the people of the East, with large herds, many servants, seven sons and three daughters. The Bible calls him blameless and upright."""),
  matters=("Why Job matters today", """Job’s story wrestles honestly with why good people suffer. It doesn’t give a simple answer, but shows that God is present, sovereign and wise, and that bringing our honest questions to Him is not wrong."""))
